describe('JavaScript Confirm Dialog Tests', () => {
    beforeEach(() => {
        cy.visit('https://the-internet.herokuapp.com/javascript_alerts');
    });

    it('should show "You clicked: Ok" when the confirm dialog is accepted', () => {
        cy.contains('Click for JS Confirm').click();
        cy.on('window:confirm', () => true); // Accept the confirm dialog
        cy.get('#result').should('have.text', 'You clicked: Ok');
    });

    it('should show "You clicked: Cancel" when the confirm dialog is dismissed', () => {
        cy.contains('Click for JS Confirm').click();
        cy.on('window:confirm', () => false); // Dismiss the confirm dialog
        cy.get('#result').should('have.text', 'You clicked: Cancel');
    });
});
